function validate([s, t]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 letters.';
  if (typeof t !== 'string' || t.length < 1 || t.length > 100000) return 't needs 1 to 100000 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase English letters.';
  return null;
}

