function minimumScore(s, t) {
  const n = s.length;
  const m = t.length;
  const suffix = new Array(m + 1).fill(-1);
  suffix[m] = n;
  let pos = n - 1;
  for (let j = m - 1; j >= 0; j--) {
    while (pos >= 0 && s[pos] !== t[j]) pos--;
    if (pos < 0) break;
    suffix[j] = pos;
    pos--;
  }
  let right = 0;
  while (suffix[right] < 0) right++;
  let best = right;
  let left = 0;
  for (let i = 0; i < n && left < m; i++) {
    if (s[i] !== t[left]) continue;
    left++;
    while (right < left || suffix[right] <= i) right++;
    best = Math.min(best, right - left);
  }
  return best;
}

