function minimumScore(s, t) {
  const m = t.length;
  let best = m;
  for (let mask = 0; mask < (1 << m); mask++) {
    let kept = '';
    let low = -1;
    let high = -1;
    for (let k = 0; k < m; k++) {
      if (mask & (1 << k)) {
        if (low < 0) low = k;
        high = k;
      } else kept += t[k];
    }
    let matched = 0;
    for (const c of s) if (matched < kept.length && c === kept[matched]) matched++;
    if (matched !== kept.length) continue;
    const score = mask === 0 ? 0 : high - low + 1;
    if (score < best) best = score;
  }
  return best;
}

