function generate(rand, size) {
  const alphabets = ['ab', 'abc', 'abcd', 'xyz'];
  const alphabet = alphabets[Math.floor(rand() * alphabets.length)];
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const word = (length) => Array.from({ length }, letter).join('');
  if (size !== 'large') {
    const s = word(1 + Math.floor(rand() * 8));
    let t = word(1 + Math.floor(rand() * 8));
    if (rand() < 0.2) t = t.slice(0, -1) + 'q';
    return [s, t];
  }
  const s = word(10000);
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [s, word(10000)];
  // Take a subsequence of s and break it with a block that s cannot supply in place.
  let kept = '';
  for (const c of s) if (rand() < 0.7) kept += c;
  const cut = Math.floor(rand() * kept.length);
  const junk = mode === 1 ? 'q'.repeat(1 + Math.floor(rand() * 50)) : word(1 + Math.floor(rand() * 3000));
  const t = (kept.slice(0, cut) + junk + kept.slice(cut)).slice(0, 10000);
  return [s, t];
}
